test("Sdk User Lifecycle", async () => {
  const testHttpClient = createTestHTTPClient("user-lifecycle");

  const authenticateOutputs = await authenticate();
  expect(authenticateOutputs).toBeDefined();
  const sdk = new SDK({
    serverURL: process.env["TEST_SERVER_URL"] ?? "http://localhost:18080",
    security: {
      userPassAuth: {
        username: "<USERNAME>",
        password: "<PASSWORD>",
      },
    },
    httpClient: testHttpClient,
  });

  const createResult = await sdk.createUser({
    email: "Trystan_Crooks@hotmail.com",
    firstName: "Trystan",
    lastName: "Crooks",
    age: 32,
    postalCode: "94110",
    metadata: {
      allergies: "none",
      additionalProperties: {
        "color": "red",
        "height": "182",
        "weight": "77",
        "is_smoking": "true",
      },
    },
  });
  expect(createResult).toBeDefined();
  expect(createResult?.email).toEqual("Trystan_Crooks@hotmail.com");
  expect(createResult?.postalCode).toBeDefined();
  expect(createResult?.postalCode).toEqual("94110");

  const getResult = await sdk.getUser(assertDefined(createResult?.id));
  expect(getResult).toBeDefined();
  expect(getResult?.email).toEqual("Trystan_Crooks@hotmail.com");
  expect(getResult?.firstName).toBeDefined();
  expect(getResult?.firstName).toEqual("Trystan");
  expect(getResult?.lastName).toBeDefined();
  expect(getResult?.lastName).toEqual("Crooks");
  expect(getResult?.age).toBeDefined();
  expect(getResult?.age).toEqual(32);
  expect(getResult?.postalCode).toBeDefined();
  expect(getResult?.postalCode).toEqual("94110");

  const user = assertDefined(getResult);
  user.postalCode = "94107";
  user.age = getResult?.age;
  const updateResult = await sdk.updateUser(
    assertDefined(createResult?.id),
    assertDefined(getResult),
  );
  expect(updateResult).toBeDefined();
  expect(updateResult?.email).toEqual("Trystan_Crooks@hotmail.com");
  expect(updateResult?.firstName).toBeDefined();
  expect(updateResult?.firstName).toEqual("Trystan");
  expect(updateResult?.lastName).toBeDefined();
  expect(updateResult?.lastName).toEqual("Crooks");
  expect(updateResult?.age).toBeDefined();
  expect(updateResult?.age).toEqual(32);
  expect(updateResult?.postalCode).toBeDefined();
  expect(updateResult?.postalCode).toEqual("94107");

  const updateAgainResult = await sdk.updateUser(
    assertDefined(createResult?.id),
    {
      id: assertDefined(createResult?.id),
      email: assertDefined(updateResult?.email),
      firstName: updateResult?.firstName,
      lastName: updateResult?.lastName,
      age: 33,
      postalCode: "94110",
      metadata: updateResult?.metadata,
    },
  );
  expect(updateAgainResult).toBeDefined();
  expect(updateAgainResult?.email).toEqual("Trystan_Crooks@hotmail.com");
  expect(updateAgainResult?.firstName).toBeDefined();
  expect(updateAgainResult?.firstName).toEqual("Trystan");
  expect(updateAgainResult?.lastName).toBeDefined();
  expect(updateAgainResult?.lastName).toEqual("Crooks");
  expect(updateAgainResult?.age).toBeDefined();
  expect(updateAgainResult?.age).toEqual(33);
  expect(updateAgainResult?.postalCode).toBeDefined();
  expect(updateAgainResult?.postalCode).toEqual("94110");

  await sdk.deleteUser(assertDefined(createResult?.id));
});

test("Sdk Update User", async () => {
  const testHttpClient = createTestHTTPClient("updateUser");

  const setupOutputs = await userSetup();
  expect(setupOutputs).toBeDefined();
  const sdk = new SDK({
    serverURL: process.env["TEST_SERVER_URL"] ?? "http://localhost:18080",
    httpClient: testHttpClient,
  });

  const user = setupOutputs.user;
  user.postalCode = "94107";
  user.age = 33;
  const result = await sdk.updateUser(setupOutputs.user.id, setupOutputs.user);
  expect(result).toBeDefined();
  expect(result?.email).toEqual("Trystan_Crooks@hotmail.com");
  expect(result?.firstName).toBeDefined();
  expect(result?.firstName).toEqual("Trystan");
  expect(result?.lastName).toBeDefined();
  expect(result?.lastName).toEqual("Crooks");
  expect(result?.age).toBeDefined();
  expect(result?.age).toEqual(33);
  expect(result?.postalCode).toBeDefined();
  expect(result?.postalCode).toEqual("94107");
  await userTeardown({
    id: setupOutputs.user.id,
  });
});

